"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function Stepper({ steps, initial = 0 }: { steps: string[]; initial?: number }) {
  const [current, setCurrent] = useState(initial);
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="w-full max-w-md">
      <ol className="flex items-center">
        {steps.map((step, i) => {
          const isComplete = i < current;
          const isActive = i === current;
          return (
            <li key={step} className="flex flex-1 items-center last:flex-none">
              <button
                type="button"
                onClick={() => setCurrent(i)}
                aria-current={isActive ? "step" : undefined}
                className="flex flex-col items-center gap-2 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600 rounded-full"
              >
                <motion.span
                  animate={isActive && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
                  transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                  className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 text-xs font-semibold transition-colors duration-300 ${
                    isComplete
                      ? "border-emerald-700 bg-emerald-700 text-white"
                      : isActive
                        ? "border-emerald-700 text-emerald-700 dark:text-emerald-400"
                        : "border-slate-300 text-slate-400 dark:border-slate-600 dark:text-slate-500"
                  }`}
                >
                  {isComplete ? (
                    <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                      <motion.path
                        d="M3 8.5l3 3 7-7.5"
                        initial={{ pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                      />
                    </svg>
                  ) : (
                    i + 1
                  )}
                </motion.span>
                <span
                  className={`text-xs font-medium ${
                    isActive ? "text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"
                  }`}
                >
                  {step}
                </span>
              </button>
              {i < steps.length - 1 && (
                <div className="mx-2 mb-5 h-0.5 flex-1 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
                  <motion.div
                    className="h-full bg-emerald-700"
                    initial={false}
                    animate={{ scaleX: isComplete ? 1 : 0 }}
                    style={{ transformOrigin: "left" }}
                    transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                  />
                </div>
              )}
            </li>
          );
        })}
      </ol>
    </div>
  );
}
